        "fonte_id": "f_bbb437fd83",
        "localizador": "L06"
      },
      {
        "fonte_id": "f_12e7f172f0",
        "localizador": "L01"
      },
      {
        "fonte_id": "f_d96520b3de",
        "localizador": "L05"
      }
    ],
    "lacunas": [
      "Faltam as precedências da ficha relacional d_aa83 necessárias para calcular o novo término e compará-lo com D10."
    ],
    "motivo": "A alteração da duração, por si só, não determina a variação do término final sem as relações entre atividades.",
    "unidade": "dia_corrido"
  },
  "custo_base": {
    "estado": "exato",
    "valor": 500000,
    "direcao": "desconhecida",
    "evidencias": [
      {
        "fonte_id": "f_bbb437fd83",
        "localizador": "L06"
      }
    ],
    "lacunas": [],
    "motivo": "A linha base fixa declara orçamento de R$5.000,00.",
    "unidade": "BRL_centavo"
  },
  "custo_novo": {
    "estado": "exato",
    "valor": 490000,
    "direcao": "desconhecida",
    "evidencias": [
      {
        "fonte_id": "f_bbb437fd83",
        "localizador": "L06"
      },
      {
        "fonte_id": "f_12e7f172f0",
        "localizador": "L01"
      },
      {
        "fonte_id": "f_e63d1b2e94",
        "localizador": "L02"
      }
    ],
    "lacunas": [],
    "motivo": "Ao custo base de 500.000 centavos aplica-se o crédito definitivo de 10.000 centavos, sem novos custos do ajuste.",
    "unidade": "BRL_centavo"
  },
  "delta_centavos": {
    "estado": "exato",
    "valor": -10000,
    "direcao": "reducao",
    "evidencias": [
      {
        "fonte_id": "f_12e7f172f0",
        "localizador": "L01"
      },
      {
        "fonte_id": "f_8ca6cc3cb4",
        "localizador": "L01"
      }
    ],
    "lacunas": [],
    "motivo": "O aviso concede crédito definitivo de R$100,00 sobre a parcela p_34ad, equivalente a 10.000 centavos de redução.",
    "unidade": "BRL_centavo"
  },
  "justificativa": "A duração do preparo cai de cinco para quatro dias, mas a ausência das precedências impede determinar se isso altera o término final. O crédito expresso reduz o custo total em 10.000 centavos."
}

